"""Generate src/structura/core/color/names.py (SVG/CSS named colours) from Qt's colour table.

The names/values are the public SVG 1.1 colour keyword list; Qt is only used as a convenient, authoritative
source so that Structura's parser accepts exactly the names Structure Synth accepted.
"""

from __future__ import annotations

from pathlib import Path

from PySide6.QtGui import QColor

OUT = Path(__file__).resolve().parents[1] / "src/structura/core/color/names.py"


def main() -> None:
    lines = [
        '"""SVG/CSS named colours (generated by tools/gen_color_names.py — do not edit)."""',
        "",
        "NAMED_COLORS: dict[str, tuple[int, int, int]] = {",
    ]
    for name in sorted({n.lower() for n in QColor.colorNames()}):
        c = QColor(name)
        lines.append(f'    "{name}": ({c.red()}, {c.green()}, {c.blue()}),')
    lines.append("}")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {OUT} ({len(lines) - 4} colours)")


if __name__ == "__main__":
    main()
